<script lang="ts">
	import { Search, SlidersHorizontal, ArrowLeft, ArrowRight, RotateCcw } from '@lucide/svelte';
	import ScholarshipCard from '$lib/components/ScholarshipCard.svelte';
	let { data } = $props();
	const degrees = ['Undergraduate','Bachelor’s','Master’s','PhD','Postdoctoral'];
	function pageHref(page: number) { const params = new URLSearchParams(); for (const key of ['q','country','degree','category','funding','sort'] as const) if (data[key]) params.set(key,data[key]); params.set('page',String(page)); return `?${params.toString()}`; }
</script>

