<section class="directory-head"><div class="container"><span class="eyebrow">Your search starts here</span><h1>Scholarship directory</h1><p>Compare real opportunities, check the details, and follow the official path to apply.</p></div></section>
<section class="directory-body"><div class="container"><form class="filters" method="GET"><label class="search-box"><Search size={18}/><input name="q" value={data.q ?? ''} placeholder="Search scholarships, providers, fields..."/><button type="submit">Search</button></label><div class="filter-grid"><label><span>Country</span><select name="country"><option value="">All countries</option>{#each data.countries as country}<option selected={data.country===country}>{country}</option>{/each}</select></label><label><span>Degree level</span><select name="degree"><option value="">All levels</option>{#each degrees as level}<option selected={data.degree===level}>{level}</option>{/each}</select></label><label><span>Category</span><select name="category"><option value="">All categories</option>{#each data.categories as item}<option value={item} selected={data.category===item}>{item}</option>{/each}</select></label><label><span>Funding</span><select name="funding"><option value="">Any funding</option>{#each data.fundingTypes as item}<option value={item} selected={data.funding===item}>{item}</option>{/each}</select></label><label><span>Sort by</span><select name="sort"><option value="deadline" selected={!data.sort||data.sort==='deadline'}>Deadline soonest</option><option value="latest" selected={data.sort==='latest'}>Recently added</option></select></label><a class="reset-link" href="/scholarships"><RotateCcw size={13}/> Reset filters</a></div></form><div class="results-row"><div><span class="result-number">{data.count}</span> verified {data.count===1?'opportunity':'opportunities'}{#if data.q}<span class="query-note"> matching “{data.q}”</span>{/if}</div><span class="results-side"><SlidersHorizontal size={14}/> Every result is admin-reviewed</span></div>
{#if !data.databaseConfigured}<div class="directory-empty"><div class="empty-art"><Search size={23}/></div><span class="eyebrow">Accurate before abundant</span><h2>We’re building your verified directory.</h2><p>Scholarships will show up here after an administrator checks each official source and application link. We don’t fill this page with guesses.</p><a class="button button-outline" href="/about">How verification works <ArrowRight size={15}/></a></div>{:else if data.rows.length}<div class="card-grid">{#each data.rows as item}<ScholarshipCard {item}/>{/each}</div><div class="pagination"><span>Page {data.page} of {Math.max(1,data.pages)}</span><div>{#if data.page>1}<a href={pageHref(data.page-1)} aria-label="Previous page"><ArrowLeft size={15}/> Previous</a>{/if}{#if data.page<data.pages}<a href={pageHref(data.page+1)} aria-label="Next page">Next <ArrowRight size={15}/></a>{/if}</div></div>{:else}<div class="directory-empty"><div class="empty-art"><Search size={23}/></div><h2>No scholarships match those filters.</h2><p>Try changing your search or clearing one of the filters to see more opportunities.</p><a class="button button-outline" href="/scholarships">Clear filters <RotateCcw size={14}/></a></div>{/if}</div></section>
